{
  "probability": 0.97,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "Bayesian update yields a high posterior (~97%) that 900+ deaths occur before April 2026 based on early 2026 pace and February incidents.",
    "March 2026 toll pace continuation is the dominant driver, with current pace implying roughly 300 more deaths to hit 900.",
    "Data gaps and weather-driven volatility inject uncertainty but are unlikely to overturn the strong signal."
  ],
  "confidence": "high",
  "narrative": "From the central Mediterranean reference class, the February 2026 pace and likely March toll drive a 97% probability of reaching 900+ deaths before April, with uncertainty mainly from data revisions and weather variability.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "reference class: Central Mediterranean fatalities per IOM Missing Migrants Project; anchor probability reflects starting point before applying updates given long-run annual totals (around 2,000+) and recent elevated early-2026 tolls."
    },
    "factor_updates": [
      {
        "factor": "March 2026 toll pace continuation",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "By late February 2026 ~606 deaths/missing; if March sustains this elevated pace, the total could exceed 900 by month-end (roughly 300 in March)."
      },
      {
        "factor": "February 2026 major incident(s)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "High-profile incidents in February lift near-term tolls and raise the probability of subsequent fatalities in March."
      },
      {
        "factor": "Unverified/missing counts and data gaps",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "IOM data gaps and revisions may push totals higher as investigations complete."
      },
      {
        "factor": "Severe weather and high hazard conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Weather shocks increase risk in winter crossings, supporting higher March tolls."
      },
      {
        "factor": "Policy crackdown and reduced arrivals",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls could reduce departures and deaths, tempering the pace though not eliminating risk."
      },
      {
        "factor": "Historical baseline and 2025 toll context",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "2025 toll around 2,185 establishes substantial baseline risk; as long-run context supports possibility of 900 by March if pace remains elevated."
      }
    ],
    "synthesis_rationale": "The final probability reflects a calibration that combines a conservative anchor with several strongly reinforcing updates (pace continuation, February incidents, data revisions, and weather), tempered by a downweighting from policy-driven reductions and data lag. The overlaps among factors are acknowledged; the posterior of 0.97 reflects a high confidence given the available signals, but remains sensitive to new incidents or revisions that could lower or raise counts."
  }
}

